-- GENERATED by build_delta_sql.mjs. Metadata, PK fingerprints and row hashes only.
BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY;
SELECT 1 / (coalesce(current_database()='artecnologia' AND current_setting('server_version_num')::int/10000=16,false)::int) AS database_guard;
SET LOCAL search_path=pg_catalog;
SET LOCAL row_security=off;
SET LOCAL timezone='UTC';
SET LOCAL datestyle='ISO, YMD';
SET LOCAL intervalstyle='iso_8601';
SET LOCAL extra_float_digits=3;
SET LOCAL bytea_output='hex';
SET LOCAL statement_timeout='120s';
SET LOCAL lock_timeout='5s';
WITH inventory(name) AS (VALUES ('public.machine_family'),('public.machine_model'),('public.machine_customs'),('public.maintenance_template'),('public.template_section'),('public.template_task'),('public.template_task_inspection'),('public.work_order'),('public.work_order_task'),('public.work_order_customs'),('public.inspection_order'),('public.inspection_order_task'),('public.desviaciones_calidad'),('public.prod_delayments'),('public.plantilla_tecnicos')),
metadata AS MATERIALIZED (
 SELECT i.name,c.oid,
 c.relkind='r' AND NOT c.relrowsecurity AND NOT c.relforcerowsecurity AND
 NOT EXISTS(SELECT FROM pg_inherits WHERE inhrelid=c.oid OR inhparent=c.oid) AND
 p.fields IS NOT NULL AND NOT EXISTS (
 SELECT FROM pg_attribute a JOIN pg_type t ON t.oid=a.atttypid
 WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped AND
 NOT (a.atttypid=ANY(ARRAY['int2'::regtype,'int4'::regtype,'int8'::regtype,'numeric'::regtype,'float4'::regtype,'float8'::regtype,'bool'::regtype,'text'::regtype,'varchar'::regtype,'bpchar'::regtype,'uuid'::regtype,'bytea'::regtype,'date'::regtype,'timestamp'::regtype,'timestamptz'::regtype,'time'::regtype,'timetz'::regtype,'interval'::regtype,'json'::regtype,'jsonb'::regtype]) OR
 t.typelem=ANY(ARRAY['int2'::regtype,'int4'::regtype,'int8'::regtype,'numeric'::regtype,'float4'::regtype,'float8'::regtype,'bool'::regtype,'text'::regtype,'varchar'::regtype,'bpchar'::regtype,'uuid'::regtype,'bytea'::regtype,'date'::regtype,'timestamp'::regtype,'timestamptz'::regtype,'time'::regtype,'timetz'::regtype,'interval'::regtype,'json'::regtype,'jsonb'::regtype]))) AS supported,
 p.fields,p.exposable,p.columns AS pk_columns,
 encode(sha256(convert_to(jsonb_build_object('columns',(
 SELECT jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,a.attidentity,a.attgenerated)
 ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
 'pk',p.columns)::text,'UTF8')),'hex') AS schema_hash
 FROM inventory i LEFT JOIN pg_class c ON c.oid=to_regclass(i.name)
 LEFT JOIN LATERAL (
 SELECT string_agg(format('%L,r.%I::text',a.attname,a.attname),',' ORDER BY k.n) AS fields,
 jsonb_agg(a.attname ORDER BY k.n) AS columns,
 bool_and(a.atttypid IN ('int2'::regtype,'int4'::regtype,'int8'::regtype,'uuid'::regtype)) AS exposable
 FROM pg_constraint p CROSS JOIN LATERAL unnest(p.conkey) WITH ORDINALITY k(attnum,n)
 JOIN pg_attribute a ON a.attrelid=p.conrelid AND a.attnum=k.attnum
 WHERE p.conrelid=c.oid AND p.contype='p' AND p.convalidated
 ) p ON true
), hashes AS MATERIALIZED (
 SELECT m.name,x.payload::jsonb AS record FROM metadata m
 CROSS JOIN LATERAL XMLTABLE('/table/row' PASSING query_to_xml(
 CASE WHEN m.supported THEN format(
 'SELECT jsonb_build_object(''kind'',''delta_row'',''name'',%L,''pk_sha256'',encode(sha256(convert_to(jsonb_build_object(%s)::text,''UTF8'')),''hex''),''pk'',%s,''row_sha256'',encode(sha256(convert_to(to_jsonb(r)::text,''UTF8'')),''hex''))::text AS payload FROM ONLY %s r',
 m.name,m.fields,CASE WHEN m.exposable THEN 'jsonb_build_object('||m.fields||')' ELSE 'NULL::jsonb' END,m.oid::regclass)
 ELSE 'SELECT NULL::text AS payload WHERE false' END,false,false,'')
 COLUMNS payload text PATH 'payload') x
), report AS (
 SELECT 0 AS position,jsonb_build_object('kind','delta_identity','database',current_database(),
 'version',current_setting('server_version'),'snapshot_visibility',pg_current_snapshot()::text,
 'started_at',transaction_timestamp(),'canonical','pg16-jsonb-v1-UTC-ISO') AS record
 UNION ALL SELECT 1,jsonb_build_object('kind','delta_table','name',m.name,'supported',coalesce(m.supported,false),
 'reason',CASE WHEN m.supported THEN NULL ELSE 'REVISAR_PK_TIPOS_O_ESTRUCTURA' END,
 'schema_sha256',m.schema_hash,'pk_columns',m.pk_columns,
 'rows',CASE WHEN m.supported THEN (SELECT count(*)::text FROM hashes h WHERE h.name=m.name) ELSE NULL END) FROM metadata m
 UNION ALL SELECT 2,record FROM hashes
 UNION ALL SELECT 3,jsonb_build_object('kind','delta_complete','tables',(SELECT count(*) FROM metadata),
 'rows',(SELECT count(*) FROM hashes),'completed_at',clock_timestamp())
) SELECT 'DELTA' AS "CHECK",'METADATO' AS "ESTADO",record AS "DETALLE" FROM report ORDER BY position,record->>'name',record->>'pk_sha256';
ROLLBACK;
